    'tool.memory_file.saved' => 'Saved: %s.',
    'tool.memory_file.secret' => 'This looks like a secret: it does not go into a memory file — secrets go into the vault (/secret).',
    'tool.memory_propose.about_person' => 'true — the fact is about another person (not the one talking, not the owner): their health, address, relations, work. Such a fact is kept only in the owner\'s memory; it cannot be proposed in a conversation without the owner.',
    'tool.memory_propose.edit' => 'For profile and summary: add — add an entry (text), replace — replace the entry old_text finds with text, remove — remove the entry old_text finds, all — the whole text anew (only when almost everything changes). Entries are separated by \'§\'.',
    'tool.memory_propose.keywords' => 'Words to find the fact by, besides its own: synonyms, loans and abbreviations (VPN / впн), names.',
